Use um conjunto para registrar o que já apareceu e uma lista para preservar a ordem: ```python
def unique_in_order(values):
    seen, result = set(), []
    for value in values:
        if value not in seen:
            seen.add(value); result.append(value)
    return result

def test_unique_in_order():
    assert unique_in_order([2, 1, 2, 3, 1]) == [2, 1, 3]
    assert unique_in_order([]) == []
``` Os testes cobrem repetição e entrada vazia.
